package com.example.smpp;
import com.cloudhopper.commons.charset.CharsetUtil;import com.cloudhopper.smpp.*;import com.cloudhopper.smpp.impl.*;import com.cloudhopper.smpp.pdu.*;import com.cloudhopper.smpp.type.Address;import com.fasterxml.jackson.databind.*;import java.nio.file.*;import java.time.LocalDateTime;import java.time.format.DateTimeFormatter;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import java.util.stream.Stream;
public class SmppJsonGateway {
 private static final ObjectMapper J=new ObjectMapper().enable(SerializationFeature.INDENT_OUTPUT);private static final DateTimeFormatter TS=DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss_SSS");private final Path base=Path.of("").toAbsolutePath(),inbox=base.resolve("sms_request"),sent=base.resolve("sms_sent"),failed=base.resolve("sms_failed"),processing=base.resolve("sms_processing");private final DefaultSmppClient client=new DefaultSmppClient(Executors.newCachedThreadPool(),32);private final Map<String,List<SmppSession>> sessions=new ConcurrentHashMap<>();private final Map<String,AtomicInteger> rr=new ConcurrentHashMap<>();
 public static void main(String[]a)throws Exception{new SmppJsonGateway().start();}
 private void start()throws Exception{for(Path p:List.of(inbox,sent,failed,processing))Files.createDirectories(p);JsonNode cfg=J.readTree(base.resolve("config/json_config.json").toFile());for(JsonNode acc:cfg.path("accounts"))bind(acc);Runtime.getRuntime().addShutdownHook(new Thread(this::shutdown));ConsoleLog.info("Watching "+inbox+"; press Ctrl+C to stop");scan();WatchService w=FileSystems.getDefault().newWatchService();inbox.register(w,StandardWatchEventKinds.ENTRY_CREATE,StandardWatchEventKinds.ENTRY_MODIFY);while(true){WatchKey k=w.poll(1,TimeUnit.SECONDS);if(k!=null){for(WatchEvent<?> e:k.pollEvents())if(e.context() instanceof Path p&&p.toString().matches("(?i)sms[0-9]+\\.json")){Thread.sleep(150);process(inbox.resolve(p));}k.reset();}scan();}}
 private void bind(JsonNode a)throws Exception{String id=req(a,"accountId");List<SmppSession> list=new ArrayList<>();for(JsonNode c:a.path("connections")){SmppSessionConfiguration x=new SmppSessionConfiguration();String cid=req(c,"connectionId");x.setName(id+"."+cid);x.setType(switch(c.path("bindType").asText("TRANSCEIVER").toUpperCase(Locale.ROOT)){case"TRANSMITTER"->SmppBindType.TRANSMITTER;case"RECEIVER"->SmppBindType.RECEIVER;default->SmppBindType.TRANSCEIVER;});x.setHost(req(c,"host"));x.setPort(c.path("port").asInt(2775));x.setSystemId(req(c,"systemId"));x.setPassword(req(c,"password"));x.setConnectTimeout(c.path("connectTimeoutMs").asInt(10000));x.setBindTimeout(c.path("bindTimeoutMs").asInt(10000));x.setRequestExpiryTimeout(30000);x.setWindowMonitorInterval(15000);x.setWindowSize(c.path("windowSize").asInt(1));x.setCountersEnabled(true);SmppSession s=client.bind(x,new DefaultSmppSessionHandler());if(!s.isBound())throw new IllegalStateException("Bind failed: "+id+"/"+cid);list.add(s);ConsoleLog.info("BOUND account="+id+" connection="+cid+" endpoint="+x.getHost()+":"+x.getPort());}if(list.isEmpty())throw new IllegalArgumentException("No connections for account "+id);sessions.put(id,List.copyOf(list));rr.put(id,new AtomicInteger());}
 private void scan()throws Exception{try(Stream<Path>s=Files.list(inbox)){for(Path p:s.filter(Files::isRegularFile).filter(p->p.getFileName().toString().matches("(?i)sms[0-9]+\\.json")).sorted().toList())process(p);}}
 private void process(Path p){if(!Files.isRegularFile(p))return;Path claimed=processing.resolve(p.getFileName());try{Files.move(p,claimed,StandardCopyOption.ATOMIC_MOVE);}catch(Exception e){try{Files.move(p,claimed);}catch(Exception ignored){return;}}JsonNode req=null;Map<String,Object> resp=new LinkedHashMap<>();resp.put("processedAt",LocalDateTime.now().toString());try{req=J.readTree(claimed.toFile());String account=req(req,"accountId"),from=req(req,"sourceAddress"),to=req(req,"destinationAddress"),message=req(req,"message");List<SmppSession> ls=sessions.get(account);if(ls==null)throw new IllegalArgumentException("Unknown accountId: "+account);SmppSession session=ls.get(Math.floorMod(rr.get(account).getAndIncrement(),ls.size()));if(!session.isBound())throw new IllegalStateException("SMPP session not bound: "+account);SubmitSm sm=new SubmitSm();sm.setSourceAddress(new Address((byte)3,(byte)0,from));sm.setDestAddress(new Address((byte)1,(byte)1,to));byte[] bytes=req.path("dataCoding").asText("GSM").equalsIgnoreCase("UTF8")?message.getBytes(java.nio.charset.StandardCharsets.UTF_8):CharsetUtil.encode(message,CharsetUtil.CHARSET_GSM);sm.setShortMessage(bytes);if(req.path("requestDeliveryReceipt").asBoolean(false))sm.setRegisteredDelivery((byte)1);ConsoleLog.submit("file="+p.getFileName()+" account="+account+" from="+from+" to="+to+" text=\""+message.replace("\n","\\n")+"\"");SubmitSmResp r=session.submit(sm,req.path("responseTimeoutMs").asInt(10000));resp.put("success",r.getCommandStatus()==0);resp.put("commandStatus",r.getCommandStatus());resp.put("resultMessage",r.getResultMessage());resp.put("messageId",r.getMessageId());resp.put("sequenceNumber",r.getSequenceNumber());resp.put("accountId",account);ConsoleLog.response("file="+p.getFileName()+" status="+r.getCommandStatus()+" ("+r.getResultMessage()+") messageId="+r.getMessageId());archive(claimed,sent,req,resp);}catch(Exception e){resp.put("success",false);resp.put("error",e.getClass().getSimpleName()+": "+e.getMessage());ConsoleLog.error("file="+p.getFileName()+" "+resp.get("error"));try{archive(claimed,failed,req,resp);}catch(Exception z){ConsoleLog.error("Archive failed: "+z);}}}
 private void archive(Path src,Path root,JsonNode request,Map<String,Object> response)throws Exception{String n=src.getFileName().toString().replaceFirst("(?i)\\.json$","");Path d=root.resolve(n+"_"+LocalDateTime.now().format(TS));Files.createDirectories(d);if(request!=null)J.writeValue(d.resolve("original_request.json").toFile(),request);else Files.copy(src,d.resolve("original_request_unparsed.json"));J.writeValue(d.resolve("submit_sm_response.json").toFile(),response);Map<String,Object> both=new LinkedHashMap<>();both.put("originalRequest",request);both.put("submitSmResponse",response);J.writeValue(d.resolve("result.json").toFile(),both);Files.deleteIfExists(src);ConsoleLog.info("ARCHIVED "+d.toAbsolutePath());}
 private static String req(JsonNode n,String f){String v=n.path(f).asText("");if(v.isBlank())throw new IllegalArgumentException("Missing JSON field: "+f);return v;}
 private void shutdown(){ConsoleLog.warn("Closing SMPP sessions");for(List<SmppSession> l:sessions.values())for(SmppSession s:l)try{if(s.isBound())s.unbind(3000);s.destroy();}catch(Exception ignored){}try{client.destroy();}catch(Exception ignored){}}
}
